var t={en:`A fleet of 3,000 devices needs signed updates; failures must halt rollout, and offline devices can update days later.`,ua:`Парк із 3 000 пристроїв потребує підписаних оновлень; збої зупиняють rollout, а офлайн-пристрої можуть оновитися через кілька днів.`};var n={en:[`Add signed artifact storage, rollout controller and device cohorts.`,`Define canary stages, health gates and rollback.`,`Isolate firmware traffic from urgent safety commands.`],ua:[`Додай сховище підписаних артефактів, контролер і групи пристроїв.`,`Визнач canary-етапи, перевірки та відкат.`,`Відокрем прошивку від критичних команд безпеки.`]};var s=[{en:`Devices verify artifacts before installing.`,ua:`Пристрої перевіряють артефакти до встановлення.`},{en:`Halted or revoked updates cannot continue dispatching.`,ua:`Зупинені або відкликані оновлення не розсилаються.`}];var r={scenario:t,tasks:n,checks:s};export{s as checks,r as default,t as scenario,n as tasks};